import { NextRequest, NextResponse } from "next/server";
import { google } from "googleapis";

const SLACK_TOKEN      = process.env.SLACK_ACCESS_TOKEN ?? "";
const SLACK_CHANNEL_ID = process.env.SLACK_CHANNEL_ID ?? "";

const GSC_SITES = [
  { name: "Cars24 – New Cars",  url: "https://www.cars24.com/new-cars/" },
  { name: "Bikes 24",           url: "sc-domain:bikes24.com" },
  { name: "TeamBHP New Cars",   url: "https://www.team-bhp.com/new-cars/" },
  { name: "TeamBHP New Bikes",  url: "https://www.team-bhp.com/new-bikes/" },
];

function getAuthClient() {
  const keyJson = process.env.GOOGLE_SERVICE_ACCOUNT_JSON;
  if (!keyJson) throw new Error("GOOGLE_SERVICE_ACCOUNT_JSON is not set in .env.local");
  const credentials = JSON.parse(keyJson);
  return new google.auth.GoogleAuth({
    credentials,
    scopes: ["https://www.googleapis.com/auth/webmasters.readonly"],
  });
}

async function gscQuery(auth: ReturnType<typeof getAuthClient>, siteUrl: string, startDate: string, endDate: string) {
  const sc = google.searchconsole({ version: "v1", auth });
  const res = await sc.searchanalytics.query({
    siteUrl,
    requestBody: { startDate, endDate },
  });
  const row = res.data.rows?.[0];
  return {
    clicks: row?.clicks ?? 0,
    position: row?.position ? +row.position.toFixed(1) : 0,
  };
}

function fmt(n: number) {
  return n.toLocaleString("en-IN");
}

async function buildAndSendReport(contentCount: number): Promise<string> {
  if (!SLACK_TOKEN) throw new Error("SLACK_ACCESS_TOKEN is not set in .env.local");
  if (!SLACK_CHANNEL_ID) throw new Error("SLACK_CHANNEL_ID is not set in .env.local");

  const auth = getAuthClient();

  // Fetch all data in parallel
  const [c24Mar, c24Feb14, c24FebFull, c24Jan, c24Dec,
         b24Mar, b24Feb14, b24FebFull, b24Jan, b24Dec,
         tbcMar, tbcFeb14, tbcFebFull, tbcJan, tbcDec,
         tbbMar, tbbFeb14, tbbFebFull, tbbJan] = await Promise.all([
    gscQuery(auth, GSC_SITES[0].url, "2026-03-01", "2026-03-14"),
    gscQuery(auth, GSC_SITES[0].url, "2026-02-01", "2026-02-14"),
    gscQuery(auth, GSC_SITES[0].url, "2026-02-01", "2026-02-28"),
    gscQuery(auth, GSC_SITES[0].url, "2026-01-01", "2026-01-31"),
    gscQuery(auth, GSC_SITES[0].url, "2025-12-01", "2025-12-31"),

    gscQuery(auth, GSC_SITES[1].url, "2026-03-01", "2026-03-14"),
    gscQuery(auth, GSC_SITES[1].url, "2026-02-01", "2026-02-14"),
    gscQuery(auth, GSC_SITES[1].url, "2026-02-01", "2026-02-28"),
    gscQuery(auth, GSC_SITES[1].url, "2026-01-01", "2026-01-31"),
    gscQuery(auth, GSC_SITES[1].url, "2025-12-01", "2025-12-31"),

    gscQuery(auth, GSC_SITES[2].url, "2026-03-01", "2026-03-14"),
    gscQuery(auth, GSC_SITES[2].url, "2026-02-01", "2026-02-14"),
    gscQuery(auth, GSC_SITES[2].url, "2026-02-01", "2026-02-28"),
    gscQuery(auth, GSC_SITES[2].url, "2026-01-01", "2026-01-31"),
    gscQuery(auth, GSC_SITES[2].url, "2025-12-01", "2025-12-31"),

    gscQuery(auth, GSC_SITES[3].url, "2026-03-01", "2026-03-14"),
    gscQuery(auth, GSC_SITES[3].url, "2026-02-01", "2026-02-14"),
    gscQuery(auth, GSC_SITES[3].url, "2026-02-01", "2026-02-28"),
    gscQuery(auth, GSC_SITES[3].url, "2026-01-01", "2026-01-31"),
  ]);

  const totalMar    = c24Mar.clicks    + b24Mar.clicks    + tbcMar.clicks    + tbbMar.clicks;
  const totalFeb14  = c24Feb14.clicks  + b24Feb14.clicks  + tbcFeb14.clicks  + tbbFeb14.clicks;
  const totalFebFull = c24FebFull.clicks + b24FebFull.clicks + tbcFebFull.clicks + tbbFebFull.clicks;
  const totalJan    = c24Jan.clicks    + b24Jan.clicks    + tbcJan.clicks    + tbbJan.clicks;
  const totalDec    = c24Dec.clicks    + b24Dec.clicks    + tbcDec.clicks;

  const slackMessage = {
    text: "New Auto – Organic Traffic Update",
    blocks: [
      {
        type: "header",
        text: { type: "plain_text", text: "🚗 New Auto – Organic Traffic Update", emoji: true },
      },
      { type: "divider" },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: `*📊 Organic Traffic (Clicks) — Google Search Console*\n\n` +
            `\`\`\`\n` +
            `${"Project".padEnd(22)} ${"1–14 Mar".padStart(10)} ${"1–14 Feb".padStart(10)} ${"Feb".padStart(9)} ${"Jan".padStart(9)} ${"Dec".padStart(9)}\n` +
            `${"─".repeat(72)}\n` +
            `${"Cars24 – New Cars".padEnd(22)} ${fmt(c24Mar.clicks).padStart(10)} ${fmt(c24Feb14.clicks).padStart(10)} ${fmt(c24FebFull.clicks).padStart(9)} ${fmt(c24Jan.clicks).padStart(9)} ${fmt(c24Dec.clicks).padStart(9)}\n` +
            `${"Bikes 24".padEnd(22)} ${fmt(b24Mar.clicks).padStart(10)} ${fmt(b24Feb14.clicks).padStart(10)} ${fmt(b24FebFull.clicks).padStart(9)} ${fmt(b24Jan.clicks).padStart(9)} ${fmt(b24Dec.clicks).padStart(9)}\n` +
            `${"TeamBHP New Cars".padEnd(22)} ${fmt(tbcMar.clicks).padStart(10)} ${fmt(tbcFeb14.clicks).padStart(10)} ${fmt(tbcFebFull.clicks).padStart(9)} ${fmt(tbcJan.clicks).padStart(9)} ${fmt(tbcDec.clicks).padStart(9)}\n` +
            `${"TeamBHP New Bikes".padEnd(22)} ${fmt(tbbMar.clicks).padStart(10)} ${fmt(tbbFeb14.clicks).padStart(10)} ${fmt(tbbFebFull.clicks).padStart(9)} ${fmt(tbbJan.clicks).padStart(9)} ${"NA".padStart(9)}\n` +
            `${"─".repeat(72)}\n` +
            `${"Total".padEnd(22)} ${fmt(totalMar).padStart(10)} ${fmt(totalFeb14).padStart(10)} ${fmt(totalFebFull).padStart(9)} ${fmt(totalJan).padStart(9)} ${fmt(totalDec).padStart(9)}\n` +
            `\`\`\``,
        },
      },
      { type: "divider" },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: `*📍 Avg Organic Position*\n\n` +
            `\`\`\`\n` +
            `${"Project".padEnd(22)} ${"Mar".padStart(8)} ${"Feb".padStart(8)} ${"Jan".padStart(8)} ${"Dec".padStart(8)}\n` +
            `${"─".repeat(57)}\n` +
            `${"Cars24 – New Cars".padEnd(22)} ${String(c24Mar.position).padStart(8)} ${String(c24FebFull.position).padStart(8)} ${String(c24Jan.position).padStart(8)} ${String(c24Dec.position).padStart(8)}\n` +
            `${"Bikes 24".padEnd(22)} ${String(b24Mar.position).padStart(8)} ${String(b24FebFull.position).padStart(8)} ${String(b24Jan.position).padStart(8)} ${String(b24Dec.position).padStart(8)}\n` +
            `${"TeamBHP New Cars".padEnd(22)} ${String(tbcMar.position).padStart(8)} ${String(tbcFebFull.position).padStart(8)} ${String(tbcJan.position).padStart(8)} ${String(tbcDec.position).padStart(8)}\n` +
            `${"TeamBHP New Bikes".padEnd(22)} ${String(tbbMar.position).padStart(8)} ${String(tbbFebFull.position).padStart(8)} ${String(tbbJan.position).padStart(8)} ${"NA".padStart(8)}\n` +
            `\`\`\``,
        },
      },
      { type: "divider" },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: `*✍️ Content Pieces Shipped*\n\n` +
            `\`\`\`\n` +
            `${"".padEnd(22)} ${"Mar".padStart(8)} ${"Feb".padStart(8)} ${"Jan".padStart(8)} ${"Dec".padStart(8)}\n` +
            `${"─".repeat(57)}\n` +
            `${"Content Pieces Shipped".padEnd(22)} ${String(contentCount).padStart(8)} ${"104".padStart(8)} ${"160".padStart(8)} ${"89".padStart(8)}\n` +
            `\`\`\``,
        },
      },
    ],
  };

  const res = await fetch(SLACK_WEBHOOK_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(slackMessage),
  });

  if (!res.ok) throw new Error(`Slack error: ${res.status} ${await res.text()}`);
  return "Report sent to #aakash-ai-experiment!";
}

export async function POST(req: NextRequest) {
  const { message, step } = await req.json() as { message: string; step: string };
  const lower = message.toLowerCase().trim();

  // Step 1: User wants to send report
  if (step === "idle" && (lower.includes("send report") || lower.includes("report"))) {
    return NextResponse.json({
      reply: "Sure! How many content pieces were shipped in March?",
      nextStep: "awaiting_count",
    });
  }

  // Step 2: User provides content count
  if (step === "awaiting_count") {
    const num = parseInt(message.replace(/[^0-9]/g, ""), 10);
    if (isNaN(num)) {
      return NextResponse.json({
        reply: "Please enter a valid number (e.g. 60).",
        nextStep: "awaiting_count",
      });
    }

    try {
      const result = await buildAndSendReport(num);
      return NextResponse.json({ reply: `✅ ${result}`, nextStep: "idle" });
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Unknown error";
      return NextResponse.json({ reply: `❌ Failed: ${msg}`, nextStep: "idle" });
    }
  }

  // Default
  return NextResponse.json({
    reply: 'Type "send report" to send the organic traffic report to Slack.',
    nextStep: "idle",
  });
}

