import { NextRequest, NextResponse } from "next/server";
import { GSC_DATA } from "@/app/data/gsc-data";

const SLACK_TOKEN      = process.env.SLACK_ACCESS_TOKEN ?? "";
const SLACK_CHANNEL_ID = process.env.SLACK_CHANNEL_ID ?? "";

function fmt(n: number | null) {
  if (n === null) return "NA";
  return n.toLocaleString("en-IN");
}

function pad(s: string, len: number) {
  return s.padStart(len);
}

async function buildAndSendReport(contentCount: number): Promise<string> {
  if (!SLACK_TOKEN)      throw new Error("SLACK_ACCESS_TOKEN is not set in .env.local");
  if (!SLACK_CHANNEL_ID) throw new Error("SLACK_CHANNEL_ID is not set in .env.local");

  const c = GSC_DATA.clicks;
  const p = GSC_DATA.position;

  const projects = ["Cars24 – New Cars", "Bikes 24", "TeamBHP New Cars", "TeamBHP New Bikes"] as const;

  const totalMar    = projects.reduce((s, k) => s + (c[k].mar    ?? 0), 0);
  const totalFeb14  = projects.reduce((s, k) => s + (c[k].feb14  ?? 0), 0);
  const totalFeb    = projects.reduce((s, k) => s + (c[k].feb    ?? 0), 0);
  const totalJan    = projects.reduce((s, k) => s + (c[k].jan    ?? 0), 0);
  const totalDec    = projects.reduce((s, k) => s + (c[k].dec    ?? 0), 0);

  const clicksTable =
    `Project               | 1–14 Mar | 1–14 Feb |     Feb |     Jan |     Dec\n` +
    `──────────────────────┼──────────┼──────────┼─────────┼─────────┼─────────\n` +
    projects.map(k =>
      `${k.padEnd(22)}| ${pad(fmt(c[k].mar), 8)} | ${pad(fmt(c[k].feb14), 8)} | ${pad(fmt(c[k].feb), 7)} | ${pad(fmt(c[k].jan), 7)} | ${pad(fmt(c[k].dec), 7)}`
    ).join("\n") + "\n" +
    `──────────────────────┼──────────┼──────────┼─────────┼─────────┼─────────\n` +
    `${"Total".padEnd(22)}| ${pad(fmt(totalMar), 8)} | ${pad(fmt(totalFeb14), 8)} | ${pad(fmt(totalFeb), 7)} | ${pad(fmt(totalJan), 7)} | ${pad(fmt(totalDec), 7)}`;

  const posTable =
    `Project               |    Mar |    Feb |    Jan |    Dec\n` +
    `──────────────────────┼────────┼────────┼────────┼────────\n` +
    projects.map(k =>
      `${k.padEnd(22)}| ${pad(String(p[k].mar ?? "NA"), 6)} | ${pad(String(p[k].feb ?? "NA"), 6)} | ${pad(String(p[k].jan ?? "NA"), 6)} | ${pad(String(p[k].dec ?? "NA"), 6)}`
    ).join("\n");

  const contentTable =
    `                       |  Mar |  Feb |  Jan |  Dec\n` +
    `───────────────────────┼──────┼──────┼──────┼──────\n` +
    `Content Pieces Shipped | ${pad(String(contentCount), 4)} |  104 |  160 |   89`;

  const blocks = [
