import { NextRequest, NextResponse } from "next/server";
import { GSC_DATA } from "@/app/data/gsc-data";

function fmt(n: number | null) {
  if (n === null) return "NA";
  return n.toLocaleString("en-IN");
}

// Returns { endDay, curLabel, prevLabel }
// e.g. today = Mar 18 → endDay = 16, curLabel = "1–16 Mar", prevLabel = "1–16 Feb"
function getDateLabels() {
  const today = new Date();
  const endDay = today.getDate() - 2;

  const curMonth = today.toLocaleString("en-US", { month: "short" });

  const prevMonthDate = new Date(today.getFullYear(), today.getMonth() - 1, 1);
  const prevMonth = prevMonthDate.toLocaleString("en-US", { month: "short" });

  return {
    endDay,
    curLabel:  `1–${endDay} ${curMonth}`,
    prevLabel: `1–${endDay} ${prevMonth}`,
  };
}

const PROJECTS = ["Cars24 – New Cars", "Bikes 24", "TeamBHP New Cars", "TeamBHP New Bikes"] as const;

function buildReport(contentCount: number) {
  const { curLabel, prevLabel } = getDateLabels();
  const d = GSC_DATA;

  const totalCur  = PROJECTS.reduce((s, k) => s + (d.curPeriod[k].clicks  ?? 0), 0);
  const totalPrev = PROJECTS.reduce((s, k) => s + (d.prevPeriod[k].clicks ?? 0), 0);
  const totalFeb  = PROJECTS.reduce((s, k) => s + (d.feb[k].clicks        ?? 0), 0);
  const totalJan  = PROJECTS.reduce((s, k) => s + (d.jan[k].clicks        ?? 0), 0);
  const totalDec  = PROJECTS.reduce((s, k) => s + (d.dec[k].clicks        ?? 0), 0);

  return {
    curLabel,
    prevLabel,
    clicks: {
      rows: PROJECTS.map((k) => ({
        name:  k,
        cur:   fmt(d.curPeriod[k].clicks),
        prev:  fmt(d.prevPeriod[k].clicks),
        feb:   fmt(d.feb[k].clicks),
        jan:   fmt(d.jan[k].clicks),
        dec:   fmt(d.dec[k].clicks),
      })),
      total: {
        cur:  fmt(totalCur),
        prev: fmt(totalPrev),
        feb:  fmt(totalFeb),
        jan:  fmt(totalJan),
        dec:  fmt(totalDec),
      },
    },
    position: PROJECTS.map((k) => ({
      name: k,
      cur:  d.curPeriod[k].position  ?? "NA",
      feb:  d.feb[k].position        ?? "NA",
      jan:  d.jan[k].position        ?? "NA",
      dec:  d.dec[k].position        ?? "NA",
    })),
    content: { mar: contentCount, feb: 104, jan: 160, dec: 89 },
  };
}

export async function POST(req: NextRequest) {
  const { message, step } = await req.json() as { message: string; step: string };
  const lower = message.toLowerCase().trim();

  if (step === "idle" && (lower.includes("send report") || lower.includes("report"))) {
    return NextResponse.json({
      reply: "Sure! How many content pieces were shipped this month?",
      nextStep: "awaiting_count",
    });
  }

  if (step === "awaiting_count") {
    const num = parseInt(message.replace(/[^0-9]/g, ""), 10);
    if (isNaN(num)) {
      return NextResponse.json({
        reply: "Please enter a valid number (e.g. 10).",
        nextStep: "awaiting_count",
      });
    }
    const report = buildReport(num);
    return NextResponse.json({
      reply: "Here's your report preview. Ask Claude to post it to Slack.",
      report,
      nextStep: "idle",
    });
  }

  return NextResponse.json({
    reply: 'Type "send report" to preview the organic traffic report.',
    nextStep: "idle",
  });
}

