export default function Home() {
  const [messages, setMessages] = useState<Message[]>([
    { role: "assistant", text: 'Hi! Type "send report" to preview the organic traffic report.' },
  ]);
  const [input, setInput]   = useState("");
  const [loading, setLoading] = useState(false);
  const [step, setStep]     = useState("idle");
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, loading]);

  async function handleSend() {
    const text = input.trim();
    if (!text || loading) return;

    const newMessages: Message[] = [...messages, { role: "user", text }];
    setMessages(newMessages);
    setInput("");
    setLoading(true);

    try {
      const res  = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: text, step }),
      });
      const data = await res.json();
      setMessages([...newMessages, { role: "assistant", text: data.reply, report: data.report }]);
      setStep(data.nextStep ?? "idle");
    } catch {
      setMessages([...newMessages, { role: "assistant", text: "Something went wrong. Please try again." }]);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-zinc-100 font-sans dark:bg-zinc-950">
      <main className="flex w-full max-w-3xl flex-col h-[90vh] bg-white dark:bg-zinc-900 rounded-2xl shadow-xl overflow-hidden border border-zinc-200 dark:border-zinc-800">

        {/* Header */}
        <div className="flex items-center gap-3 px-6 py-4 border-b border-zinc-100 dark:border-zinc-800">
          <div className="w-2.5 h-2.5 rounded-full bg-green-500" />
